edits.after:
static int __init c6xdigio_init_module(void)
{
	int ret;

	ret = pnp_register_driver(&c6xdigio_pnp_driver);
	if (ret < 0)
		return ret;

	ret = comedi_driver_register(&c6xdigio_driver);
	if (ret < 0) {
		pnp_unregister_driver(&c6xdigio_pnp_driver);
		return ret;
	}

	return 0;
}
module_init(c6xdigio_init_module);

static void __exit c6xdigio_cleanup_module(void)
{
	comedi_driver_unregister(&c6xdigio_driver);
	pnp_unregister_driver(&c6xdigio_pnp_driver);
}
module_exit(c6xdigio_cleanup_module);

